    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([100]), fmt([1, 1]), fmt([2, 2, 2]), fmt([1] * 12), fmt([5, 5, 5, 5]),
