    for n in (2, 3, 5, 7, 9, 11, 12):
        for _ in range(3):
            tests.append(fmt([rng.randint(1, 10) for _ in range(n)]))
    for _ in range(4):
        tests.append(fmt([rng.randint(1, 100) for _ in range(12)]))
    tests.append(fmt([rng.randint(1, 100) for _ in range(40)]))
    tests.append(fmt([100] * 100))
    tests.append(fmt([rng.randint(1, 100) for _ in range(100)]))
    tests.append(fmt([rng.randint(95, 100) for _ in range(100)]))
    tests.append(fmt([1] * 100))
    tests.append(fmt([rng.choice([1, 2, 99, 100]) for _ in range(100)]))
    return tests

